package com.leshao.v3;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.util.Base64;

public final class IconData {
    private static final String B64_0 = "";
    private static final String B64_1 = "";
    private static final String B64_2 = "";
    private static final String B64_3 = "";
    private static final String B64_4 = "";

    private static Bitmap[] sCache = new Bitmap[5];

    private IconData() {}

    public static Bitmap getIcon(int iconId) {
        if (iconId < 0 || iconId >= 5) return null;
        Bitmap cached = sCache[iconId];
        if (cached != null) return cached;
        try {
            String b64 = null;
            switch (iconId) {
                case 0: b64 = B64_0; break;
                case 1: b64 = B64_1; break;
                case 2: b64 = B64_2; break;
                case 3: b64 = B64_3; break;
                case 4: b64 = B64_4; break;
            }
            byte[] data = Base64.decode(b64, Base64.DEFAULT);
            Bitmap bmp = BitmapFactory.decodeByteArray(data, 0, data.length);
            sCache[iconId] = bmp;
            return bmp;
        } catch (Exception e) {
            return null;
        }
    }

    public static Drawable getDrawable(int iconId) {
        Bitmap bmp = getIcon(iconId);
        if (bmp == null) return null;
        return new BitmapDrawable(bmp);
    }
}
